116	interface MessageBranchContextType {
117	  currentBranch: number;
118	  totalBranches: number;
119	  goToPrevious: () => void;
120	  goToNext: () => void;
121	  branches: ReactElement[];
122	  setBranches: (branches: ReactElement[]) => void;
123	}
124	
125	const MessageBranchContext = createContext<MessageBranchContextType | null>(
126	  null
127	);
128	
129	const useMessageBranch = () => {
130	  const context = useContext(MessageBranchContext);
131	
132	  if (!context) {
133	    throw new Error(
134	      "MessageBranch components must be used within MessageBranch"
135	    );
136	  }
137	
138	  return context;
139	};
140	
141	export type MessageBranchProps = HTMLAttributes<HTMLDivElement> & {
142	  defaultBranch?: number;
143	  onBranchChange?: (branchIndex: number) => void;
144	};
145	
146	export const MessageBranch = ({
147	  defaultBranch = 0,
148	  onBranchChange,
149	  className,
150	  ...props
151	}: MessageBranchProps) => {
152	  const [currentBranch, setCurrentBranch] = useState(defaultBranch);
153	  const [branches, setBranches] = useState<ReactElement[]>([]);
154	
155	  const handleBranchChange = useCallback(
156	    (newBranch: number) => {
157	      setCurrentBranch(newBranch);
158	      onBranchChange?.(newBranch);
159	    },
160	    [onBranchChange]
161	  );
162	
163	  const goToPrevious = useCallback(() => {
164	    const newBranch =
165	      currentBranch > 0 ? currentBranch - 1 : branches.length - 1;
166	    handleBranchChange(newBranch);
167	  }, [currentBranch, branches.length, handleBranchChange]);
168	
169	  const goToNext = useCallback(() => {
170	    const newBranch =
171	      currentBranch < branches.length - 1 ? currentBranch + 1 : 0;
172	    handleBranchChange(newBranch);
173	  }, [currentBranch, branches.length, handleBranchChange]);
174	
175	  const contextValue = useMemo<MessageBranchContextType>(
176	    () => ({
177	      branches,
178	      currentBranch,
179	      goToNext,
180	      goToPrevious,
181	      setBranches,
182	      totalBranches: branches.length,
183	    }),
184	    [branches, currentBranch, goToNext, goToPrevious]
185	  );
186	
187	  return (
188	    <MessageBranchContext.Provider value={contextValue}>
189	      <div
190	        className={cn("grid w-full gap-2 [&>div]:pb-0", className)}
191	        {...props}
192	      />
193	    </MessageBranchContext.Provider>
194	  );
195	};
