200	  children,
201	  ...props
202	}: MessageBranchContentProps) => {
203	  const { currentBranch, setBranches, branches } = useMessageBranch();
204	  const childrenArray = useMemo(
205	    () => (Array.isArray(children) ? children : [children]),
206	    [children]
207	  );
208	
209	  // Use useEffect to update branches when they change
210	  useEffect(() => {
211	    if (branches.length !== childrenArray.length) {
212	      setBranches(childrenArray);
213	    }
214	  }, [childrenArray, branches, setBranches]);
215	
216	  return childrenArray.map((branch, index) => (
217	    <div
218	      className={cn(
219	        "grid gap-2 overflow-hidden [&>div]:pb-0",
220	        index === currentBranch ? "block" : "hidden"
221	      )}
222	      key={branch.key}
223	      {...props}
224	    >
