81	const convertBlobUrlToDataUrl = async (url: string): Promise<string | null> => {
82	  try {
83	    const response = await fetch(url);
84	    const blob = await response.blob();
85	    // FileReader uses callback-based API, wrapping in Promise is necessary
86	    // oxlint-disable-next-line eslint-plugin-promise(avoid-new)
87	    return new Promise((resolve) => {
88	      const reader = new FileReader();
89	      // oxlint-disable-next-line eslint-plugin-unicorn(prefer-add-event-listener)
90	      reader.onloadend = () => resolve(reader.result as string);
91	      // oxlint-disable-next-line eslint-plugin-unicorn(prefer-add-event-listener)
92	      reader.onerror = () => resolve(null);
93	      reader.readAsDataURL(blob);
94	    });
95	  } catch {
96	    return null;
97	  }
98	};
