100	const captureScreenshot = async (): Promise<File | null> => {
101	  if (
102	    typeof navigator === "undefined" ||
103	    !navigator.mediaDevices?.getDisplayMedia
104	  ) {
105	    return null;
106	  }
107	
108	  let stream: MediaStream | null = null;
109	  const video = document.createElement("video");
110	  video.muted = true;
111	  video.playsInline = true;
112	
113	  try {
114	    stream = await navigator.mediaDevices.getDisplayMedia({
115	      audio: false,
116	      video: true,
117	    });
118	
119	    video.srcObject = stream;
120	
121	    // Video element uses callback-based API, wrapping in Promise is necessary
122	    // oxlint-disable-next-line eslint-plugin-promise(avoid-new)
123	    await new Promise<void>((resolve, reject) => {
124	      // oxlint-disable-next-line eslint-plugin-unicorn(prefer-add-event-listener)
125	      video.onloadedmetadata = () => resolve();
126	      // oxlint-disable-next-line eslint-plugin-unicorn(prefer-add-event-listener)
127	      video.onerror = () => reject(new Error("Failed to load screen stream"));
128	    });
129	
130	    await video.play();
131	
132	    const width = video.videoWidth;
133	    const height = video.videoHeight;
134	    if (!width || !height) {
135	      return null;
136	    }
137	
138	    const canvas = document.createElement("canvas");
139	    canvas.width = width;
140	    canvas.height = height;
141	    const context = canvas.getContext("2d");
142	    if (!context) {
143	      return null;
144	    }
145	
146	    context.drawImage(video, 0, 0, width, height);
147	    // canvas.toBlob uses callback-based API, wrapping in Promise is necessary
148	    // oxlint-disable-next-line eslint-plugin-promise(avoid-new)
149	    const blob = await new Promise<Blob | null>((resolve) => {
150	      canvas.toBlob(resolve, "image/png");
151	    });
152	    if (!blob) {
153	      return null;
154	    }
155	
156	    const timestamp = new Date()
157	      .toISOString()
158	      .replaceAll(/[:.]/g, "-")
159	      .replace("T", "_")
160	      .replace("Z", "");
161	
162	    return new File([blob], `screenshot-${timestamp}.png`, {
163	      lastModified: Date.now(),
164	      type: "image/png",
165	    });
166	  } finally {
167	    if (stream) {
168	      for (const track of stream.getTracks()) {
169	        track.stop();
170	      }
171	    }
172	    video.pause();
173	    video.srcObject = null;
174	  }
175	};
