259	  >([]);
260	  const fileInputRef = useRef<HTMLInputElement | null>(null);
261	  // oxlint-disable-next-line eslint(no-empty-function)
262	  const openRef = useRef<() => void>(() => {});
263	
264	  const add = useCallback((files: File[] | FileList) => {
265	    const incoming = [...files];
266	    if (incoming.length === 0) {
267	      return;
268	    }
269	
270	    setAttachmentFiles((prev) => [
271	      ...prev,
272	      ...incoming.map((file) => ({
273	        filename: file.name,
274	        id: nanoid(),
275	        mediaType: file.type,
276	        type: "file" as const,
277	        url: URL.createObjectURL(file),
278	      })),
279	    ]);
280	  }, []);
281	
282	  const remove = useCallback((id: string) => {
283	    setAttachmentFiles((prev) => {
284	      const found = prev.find((f) => f.id === id);
285	      if (found?.url) {
286	        URL.revokeObjectURL(found.url);
287	      }
288	      return prev.filter((f) => f.id !== id);
289	    });
290	  }, []);
291	
292	  const clear = useCallback(() => {
293	    setAttachmentFiles((prev) => {
294	      for (const f of prev) {
295	        if (f.url) {
296	          URL.revokeObjectURL(f.url);
297	        }
298	      }
299	      return [];
300	    });
301	  }, []);
302	
303	  // Keep a ref to attachments for cleanup on unmount (avoids stale closure)
304	  const attachmentsRef = useRef(attachmentFiles);
305	
306	  useEffect(() => {
307	    attachmentsRef.current = attachmentFiles;
308	  }, [attachmentFiles]);
309	
310	  // Cleanup blob URLs on unmount to prevent memory leaks
311	  useEffect(
312	    () => () => {
313	      for (const f of attachmentsRef.current) {
314	        if (f.url) {
315	          URL.revokeObjectURL(f.url);
316	        }
317	      }
318	    },
319	    []
320	  );
321	
322	  const openFileDialog = useCallback(() => {
323	    openRef.current?.();
324	  }, []);
325	
326	  const attachments = useMemo<AttachmentsContext>(
327	    () => ({
328	      add,
329	      clear,
330	      fileInputRef,
331	      files: attachmentFiles,
332	      openFileDialog,
333	      remove,
334	    }),
335	    [attachmentFiles, add, remove, clear, openFileDialog]
336	  );
337	
338	  const __registerFileInput = useCallback(
339	    (ref: RefObject<HTMLInputElement | null>, open: () => void) => {
340	      fileInputRef.current = ref.current;
341	      openRef.current = open;
342	    },
343	    []
344	  );
345	
346	  const controller = useMemo<PromptInputControllerProps>(
347	    () => ({
348	      __registerFileInput,
349	      attachments,
350	      textInput: {
351	        clear: clearInput,
352	        setInput: setTextInput,
353	        value: textInput,
354	      },
355	    }),
356	    [textInput, clearInput, attachments, __registerFileInput]
357	  );
358	
359	  return (
360	    <PromptInputController.Provider value={controller}>
361	      <ProviderAttachmentsContext.Provider value={attachments}>
362	        {children}
363	      </ProviderAttachmentsContext.Provider>
364	    </PromptInputController.Provider>
365	  );
366	};
