374	export const usePromptInputAttachments = () => {
375	  // Prefer local context (inside PromptInput) as it has validation, fall back to provider
376	  const provider = useOptionalProviderAttachments();
377	  const local = useContext(LocalAttachmentsContext);
378	  const context = local ?? provider;
379	  if (!context) {
380	    throw new Error(
381	      "usePromptInputAttachments must be used within a PromptInput or PromptInputProvider"
382	    );
383	  }
384	  return context;
385	};
