484	export interface PromptInputMessage {
485	  text: string;
486	  files: FileUIPart[];
487	}
488	
489	export type PromptInputProps = Omit<
490	  HTMLAttributes<HTMLFormElement>,
491	  "onSubmit" | "onError"
492	> & {
493	  // e.g., "image/*" or leave undefined for any
494	  accept?: string;
495	  multiple?: boolean;
496	  // When true, accepts drops anywhere on document. Default false (opt-in).
497	  globalDrop?: boolean;
498	  // Render a hidden input with given name and keep it in sync for native form posts. Default false.
499	  syncHiddenInput?: boolean;
500	  // Minimal constraints
501	  maxFiles?: number;
502	  // bytes
503	  maxFileSize?: number;
504	  onError?: (err: {
505	    code: "max_files" | "max_file_size" | "accept";
506	    message: string;
507	  }) => void;
508	  onSubmit: (
509	    message: PromptInputMessage,
510	    event: FormEvent<HTMLFormElement>
511	  ) => void | Promise<void>;
512	};
513	
514	export const PromptInput = ({
515	  className,
516	  accept,
517	  multiple,
518	  globalDrop,
519	  syncHiddenInput,
520	  maxFiles,
521	  maxFileSize,
522	  onError,
523	  onSubmit,
524	  children,
525	  ...props
526	}: PromptInputProps) => {
527	  // Try to use a provider controller if present
528	  const controller = useOptionalPromptInputController();
529	  const usingProvider = !!controller;
530	
531	  // Refs
532	  const inputRef = useRef<HTMLInputElement | null>(null);
533	  const formRef = useRef<HTMLFormElement | null>(null);
534	
535	  // ----- Local attachments (only used when no provider)
536	  const [items, setItems] = useState<(FileUIPart & { id: string })[]>([]);
537	  const files = usingProvider ? controller.attachments.files : items;
538	
539	  // ----- Local referenced sources (always local to PromptInput)
540	  const [referencedSources, setReferencedSources] = useState<
541	    (SourceDocumentUIPart & { id: string })[]
542	  >([]);
543	
544	  // Keep a ref to files for cleanup on unmount (avoids stale closure)
545	  const filesRef = useRef(files);
546	
547	  useEffect(() => {
548	    filesRef.current = files;
549	  }, [files]);
550	
551	  const openFileDialogLocal = useCallback(() => {
552	    inputRef.current?.click();
553	  }, []);
554	
555	  const matchesAccept = useCallback(
556	    (f: File) => {
557	      if (!accept || accept.trim() === "") {
558	        return true;
559	      }
560	
561	      const patterns = accept
562	        .split(",")
563	        .map((s) => s.trim())
564	        .filter(Boolean);
565	
566	      return patterns.some((pattern) => {
567	        if (pattern.endsWith("/*")) {
568	          // e.g: image/* -> image/
569	          const prefix = pattern.slice(0, -1);
570	          return f.type.startsWith(prefix);
571	        }
572	        return f.type === pattern;
573	      });
574	    },
575	    [accept]
576	  );
577	
578	  const addLocal = useCallback(
579	    (fileList: File[] | FileList) => {
580	      const incoming = [...fileList];
581	      const accepted = incoming.filter((f) => matchesAccept(f));
582	      if (incoming.length && accepted.length === 0) {
583	        onError?.({
584	          code: "accept",
585	          message: "No files match the accepted types.",
586	        });
587	        return;
588	      }
589	      const withinSize = (f: File) =>
590	        maxFileSize ? f.size <= maxFileSize : true;
591	      const sized = accepted.filter(withinSize);
592	      if (accepted.length > 0 && sized.length === 0) {
593	        onError?.({
594	          code: "max_file_size",
595	          message: "All files exceed the maximum size.",
596	        });
597	        return;
598	      }
599	
600	      setItems((prev) => {
601	        const capacity =
602	          typeof maxFiles === "number"
603	            ? Math.max(0, maxFiles - prev.length)
604	            : undefined;
605	        const capped =
606	          typeof capacity === "number" ? sized.slice(0, capacity) : sized;
607	        if (typeof capacity === "number" && sized.length > capacity) {
608	          onError?.({
609	            code: "max_files",
610	            message: "Too many files. Some were not added.",
611	          });
612	        }
613	        const next: (FileUIPart & { id: string })[] = [];
614	        for (const file of capped) {
615	          next.push({
616	            filename: file.name,
617	            id: nanoid(),
618	            mediaType: file.type,
619	            type: "file",
620	            url: URL.createObjectURL(file),
621	          });
622	        }
623	        return [...prev, ...next];
624	      });
625	    },
626	    [matchesAccept, maxFiles, maxFileSize, onError]
627	  );
628	
629	  const removeLocal = useCallback(
630	    (id: string) =>
631	      setItems((prev) => {
632	        const found = prev.find((file) => file.id === id);
633	        if (found?.url) {
634	          URL.revokeObjectURL(found.url);
635	        }
636	        return prev.filter((file) => file.id !== id);
637	      }),
638	    []
639	  );
640	
641	  // Wrapper that validates files before calling provider's add
642	  const addWithProviderValidation = useCallback(
643	    (fileList: File[] | FileList) => {
644	      const incoming = [...fileList];
645	      const accepted = incoming.filter((f) => matchesAccept(f));
646	      if (incoming.length && accepted.length === 0) {
647	        onError?.({
648	          code: "accept",
649	          message: "No files match the accepted types.",
650	        });
651	        return;
652	      }
653	      const withinSize = (f: File) =>
654	        maxFileSize ? f.size <= maxFileSize : true;
655	      const sized = accepted.filter(withinSize);
656	      if (accepted.length > 0 && sized.length === 0) {
657	        onError?.({
658	          code: "max_file_size",
659	          message: "All files exceed the maximum size.",
660	        });
661	        return;
662	      }
663	
664	      const currentCount = files.length;
665	      const capacity =
666	        typeof maxFiles === "number"
667	          ? Math.max(0, maxFiles - currentCount)
668	          : undefined;
669	      const capped =
670	        typeof capacity === "number" ? sized.slice(0, capacity) : sized;
671	      if (typeof capacity === "number" && sized.length > capacity) {
672	        onError?.({
673	          code: "max_files",
674	          message: "Too many files. Some were not added.",
675	        });
676	      }
677	
678	      if (capped.length > 0) {
679	        controller?.attachments.add(capped);
680	      }
681	    },
682	    [matchesAccept, maxFileSize, maxFiles, onError, files.length, controller]
683	  );
684	
685	  const clearAttachments = useCallback(
686	    () =>
687	      usingProvider
688	        ? controller?.attachments.clear()
689	        : setItems((prev) => {
690	            for (const file of prev) {
691	              if (file.url) {
692	                URL.revokeObjectURL(file.url);
693	              }
694	            }
695	            return [];
696	          }),
697	    [usingProvider, controller]
698	  );
699	
700	  const clearReferencedSources = useCallback(
701	    () => setReferencedSources([]),
702	    []
703	  );
704	
705	  const add = usingProvider ? addWithProviderValidation : addLocal;
706	  const remove = usingProvider ? controller.attachments.remove : removeLocal;
707	  const openFileDialog = usingProvider
708	    ? controller.attachments.openFileDialog
709	    : openFileDialogLocal;
710	
711	  const clear = useCallback(() => {
712	    clearAttachments();
713	    clearReferencedSources();
714	  }, [clearAttachments, clearReferencedSources]);
715	
716	  // Let provider know about our hidden file input so external menus can call openFileDialog()
717	  useEffect(() => {
718	    if (!usingProvider) {
719	      return;
720	    }
721	    controller.__registerFileInput(inputRef, () => inputRef.current?.click());
722	  }, [usingProvider, controller]);
723	
724	  // Note: File input cannot be programmatically set for security reasons
725	  // The syncHiddenInput prop is no longer functional
726	  useEffect(() => {
727	    if (syncHiddenInput && inputRef.current && files.length === 0) {
728	      inputRef.current.value = "";
729	    }
730	  }, [files, syncHiddenInput]);
731	
732	  // Attach drop handlers on nearest form and document (opt-in)
733	  useEffect(() => {
734	    const form = formRef.current;
735	    if (!form) {
736	      return;
737	    }
738	    if (globalDrop) {
739	      // when global drop is on, let the document-level handler own drops
740	      return;
741	    }
742	
743	    const onDragOver = (e: DragEvent) => {
744	      if (e.dataTransfer?.types?.includes("Files")) {
745	        e.preventDefault();
746	      }
747	    };
748	    const onDrop = (e: DragEvent) => {
749	      if (e.dataTransfer?.types?.includes("Files")) {
750	        e.preventDefault();
751	      }
752	      if (e.dataTransfer?.files && e.dataTransfer.files.length > 0) {
753	        add(e.dataTransfer.files);
754	      }
755	    };
756	    form.addEventListener("dragover", onDragOver);
757	    form.addEventListener("drop", onDrop);
758	    return () => {
759	      form.removeEventListener("dragover", onDragOver);
760	      form.removeEventListener("drop", onDrop);
761	    };
762	  }, [add, globalDrop]);
763	
764	  useEffect(() => {
765	    if (!globalDrop) {
766	      return;
767	    }
768	
769	    const onDragOver = (e: DragEvent) => {
770	      if (e.dataTransfer?.types?.includes("Files")) {
771	        e.preventDefault();
772	      }
773	    };
774	    const onDrop = (e: DragEvent) => {
775	      if (e.dataTransfer?.types?.includes("Files")) {
776	        e.preventDefault();
777	      }
778	      if (e.dataTransfer?.files && e.dataTransfer.files.length > 0) {
779	        add(e.dataTransfer.files);
780	      }
781	    };
782	    document.addEventListener("dragover", onDragOver);
783	    document.addEventListener("drop", onDrop);
784	    return () => {
785	      document.removeEventListener("dragover", onDragOver);
786	      document.removeEventListener("drop", onDrop);
787	    };
788	  }, [add, globalDrop]);
789	
790	  useEffect(
791	    () => () => {
792	      if (!usingProvider) {
793	        for (const f of filesRef.current) {
794	          if (f.url) {
795	            URL.revokeObjectURL(f.url);
796	          }
797	        }
798	      }
799	    },
800	    [usingProvider]
801	  );
802	
803	  const handleChange: ChangeEventHandler<HTMLInputElement> = useCallback(
804	    (event) => {
805	      if (event.currentTarget.files) {
806	        add(event.currentTarget.files);
807	      }
808	      // Reset input value to allow selecting files that were previously removed
809	      event.currentTarget.value = "";
810	    },
811	    [add]
812	  );
813	
814	  const attachmentsCtx = useMemo<AttachmentsContext>(
815	    () => ({
816	      add,
817	      clear: clearAttachments,
818	      fileInputRef: inputRef,
819	      files: files.map((item) => ({ ...item, id: item.id })),
820	      openFileDialog,
821	      remove,
822	    }),
823	    [files, add, remove, clearAttachments, openFileDialog]
824	  );
825	
826	  const refsCtx = useMemo<ReferencedSourcesContext>(
827	    () => ({
828	      add: (incoming: SourceDocumentUIPart[] | SourceDocumentUIPart) => {
829	        const array = Array.isArray(incoming) ? incoming : [incoming];
830	        setReferencedSources((prev) => [
831	          ...prev,
832	          ...array.map((s) => ({ ...s, id: nanoid() })),
833	        ]);
834	      },
835	      clear: clearReferencedSources,
836	      remove: (id: string) => {
837	        setReferencedSources((prev) => prev.filter((s) => s.id !== id));
838	      },
839	      sources: referencedSources,
840	    }),
841	    [referencedSources, clearReferencedSources]
842	  );
843	
844	  const handleSubmit: FormEventHandler<HTMLFormElement> = useCallback(
845	    async (event) => {
846	      event.preventDefault();
847	
848	      const form = event.currentTarget;
849	      const text = usingProvider
850	        ? controller.textInput.value
851	        : (() => {
852	            const formData = new FormData(form);
853	            return (formData.get("message") as string) || "";
854	          })();
855	
856	      // Reset form immediately after capturing text to avoid race condition
857	      // where user input during async blob conversion would be lost
858	      if (!usingProvider) {
859	        form.reset();
860	      }
861	
862	      try {
863	        // Convert blob URLs to data URLs asynchronously
864	        const convertedFiles: FileUIPart[] = await Promise.all(
865	          files.map(async ({ id: _id, ...item }) => {
866	            if (item.url?.startsWith("blob:")) {
867	              const dataUrl = await convertBlobUrlToDataUrl(item.url);
868	              // If conversion failed, keep the original blob URL
869	              return {
870	                ...item,
871	                url: dataUrl ?? item.url,
872	              };
873	            }
874	            return item;
875	          })
876	        );
877	
878	        const result = onSubmit({ files: convertedFiles, text }, event);
879	
880	        // Handle both sync and async onSubmit
881	        if (result instanceof Promise) {
882	          try {
883	            await result;
884	            clear();
885	            if (usingProvider) {
886	              controller.textInput.clear();
887	            }
888	          } catch {
889	            // Don't clear on error - user may want to retry
890	          }
891	        } else {
892	          // Sync function completed without throwing, clear inputs
893	          clear();
894	          if (usingProvider) {
895	            controller.textInput.clear();
896	          }
897	        }
898	      } catch {
899	        // Don't clear on error - user may want to retry
900	      }
901	    },
902	    [usingProvider, controller, files, onSubmit, clear]
903	  );
904	
905	  // Render with or without local provider
906	  const inner = (
907	    <>
908	      <input
909	        accept={accept}
910	        aria-label="Upload files"
911	        className="hidden"
912	        multiple={multiple}
913	        onChange={handleChange}
914	        ref={inputRef}
915	        title="Upload files"
916	        type="file"
917	      />
918	      <form
919	        className={cn("w-full", className)}
920	        onSubmit={handleSubmit}
921	        ref={formRef}
922	        {...props}
923	      >
924	        <InputGroup className="overflow-hidden">{children}</InputGroup>
925	      </form>
926	    </>
927	  );
928	
929	  const withReferencedSources = (
930	    <LocalReferencedSourcesContext.Provider value={refsCtx}>
931	      {inner}
932	    </LocalReferencedSourcesContext.Provider>
933	  );
934	
935	  // Always provide LocalAttachmentsContext so children get validated add function
936	  return (
937	    <LocalAttachmentsContext.Provider value={attachmentsCtx}>
938	      {withReferencedSources}
939	    </LocalAttachmentsContext.Provider>
940	  );
941	};
