943	export type PromptInputBodyProps = HTMLAttributes<HTMLDivElement>;
944	
945	export const PromptInputBody = ({
946	  className,
947	  ...props
948	}: PromptInputBodyProps) => (
949	  <div className={cn("contents", className)} {...props} />
950	);
