952	export type PromptInputTextareaProps = ComponentProps<
953	  typeof InputGroupTextarea
954	>;
955	
956	export const PromptInputTextarea = ({
957	  onChange,
958	  onKeyDown,
959	  className,
960	  placeholder = "What would you like to know?",
961	  ...props
962	}: PromptInputTextareaProps) => {
963	  const controller = useOptionalPromptInputController();
964	  const attachments = usePromptInputAttachments();
965	  const [isComposing, setIsComposing] = useState(false);
966	
967	  const handleKeyDown: KeyboardEventHandler<HTMLTextAreaElement> = useCallback(
968	    (e) => {
969	      // Call the external onKeyDown handler first
970	      onKeyDown?.(e);
971	
972	      // If the external handler prevented default, don't run internal logic
973	      if (e.defaultPrevented) {
974	        return;
975	      }
976	
977	      if (e.key === "Enter") {
978	        if (isComposing || e.nativeEvent.isComposing) {
979	          return;
980	        }
981	        if (e.shiftKey) {
982	          return;
983	        }
984	        e.preventDefault();
985	
986	        // Check if the submit button is disabled before submitting
987	        const { form } = e.currentTarget;
988	        const submitButton = form?.querySelector(
989	          'button[type="submit"]'
990	        ) as HTMLButtonElement | null;
991	        if (submitButton?.disabled) {
992	          return;
993	        }
994	
995	        form?.requestSubmit();
996	      }
997	
998	      // Remove last attachment when Backspace is pressed and textarea is empty
999	      if (
1000	        e.key === "Backspace" &&
1001	        e.currentTarget.value === "" &&
1002	        attachments.files.length > 0
1003	      ) {
1004	        e.preventDefault();
1005	        const lastAttachment = attachments.files.at(-1);
1006	        if (lastAttachment) {
1007	          attachments.remove(lastAttachment.id);
1008	        }
1009	      }
1010	    },
1011	    [onKeyDown, isComposing, attachments]
1012	  );
1013	
1014	  const handlePaste: ClipboardEventHandler<HTMLTextAreaElement> = useCallback(
1015	    (event) => {
1016	      const items = event.clipboardData?.items;
1017	
1018	      if (!items) {
1019	        return;
1020	      }
1021	
1022	      const files: File[] = [];
1023	
1024	      for (const item of items) {
1025	        if (item.kind === "file") {
1026	          const file = item.getAsFile();
1027	          if (file) {
1028	            files.push(file);
1029	          }
1030	        }
1031	      }
1032	
1033	      if (files.length > 0) {
1034	        event.preventDefault();
1035	        attachments.add(files);
1036	      }
1037	    },
1038	    [attachments]
1039	  );
1040	
1041	  const handleCompositionEnd = useCallback(() => setIsComposing(false), []);
1042	  const handleCompositionStart = useCallback(() => setIsComposing(true), []);
