@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));

@theme inline {
    --font-heading: var(--font-sans);
    --font-sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    --font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    --color-sidebar-ring: var(--sidebar-ring);
    --color-sidebar-border: var(--sidebar-border);
    --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
    --color-sidebar-accent: var(--sidebar-accent);
    --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
    --color-sidebar-primary: var(--sidebar-primary);
    --color-sidebar-foreground: var(--sidebar-foreground);
    --color-sidebar: var(--sidebar);
    --color-ring: var(--ring);
    --color-input: var(--input);
    --color-border: var(--border);
    --color-destructive: var(--destructive);
    --color-accent-foreground: var(--accent-foreground);
    --color-accent: var(--accent);
    --color-muted-foreground: var(--muted-foreground);
    --color-muted: var(--muted);
    --color-secondary-foreground: var(--secondary-foreground);
    --color-secondary: var(--secondary);
    --color-primary-foreground: var(--primary-foreground);
    --color-primary: var(--primary);
    --color-popover-foreground: var(--popover-foreground);
    --color-popover: var(--popover);
    --color-card-foreground: var(--card-foreground);
    --color-card: var(--card);
    --color-foreground: var(--foreground);
    --color-background: var(--background);
    --radius-sm: calc(var(--radius) * 0.6);
    --radius-md: calc(var(--radius) * 0.8);
    --radius-lg: var(--radius);
    --radius-xl: calc(var(--radius) * 1.4);
    --radius-2xl: calc(var(--radius) * 1.8);
    --radius-3xl: calc(var(--radius) * 2.2);
    --radius-4xl: calc(var(--radius) * 2.6);
}

/* Calm light surface: stone neutrals with one emerald accent (Tailwind palette values). */
:root {
    --background: oklch(0.985 0.001 106.423);      /* stone-50 */
    --foreground: oklch(0.216 0.006 56.043);       /* stone-900 */
    --card: oklch(1 0 0);
    --card-foreground: oklch(0.216 0.006 56.043);
    --popover: oklch(1 0 0);
    --popover-foreground: oklch(0.216 0.006 56.043);
    --primary: oklch(0.508 0.118 165.612);         /* emerald-700 */
    --primary-foreground: oklch(0.979 0.021 166.113);
    --secondary: oklch(0.97 0.001 106.424);        /* stone-100 */
    --secondary-foreground: oklch(0.268 0.007 34.298);
    --muted: oklch(0.97 0.001 106.424);
    --muted-foreground: oklch(0.553 0.013 58.071); /* stone-500 */
    --accent: oklch(0.97 0.001 106.424);
    --accent-foreground: oklch(0.268 0.007 34.298);
    --destructive: oklch(0.577 0.245 27.325);
    --border: oklch(0.923 0.003 48.717);           /* stone-200 */
    --input: oklch(0.923 0.003 48.717);
    --ring: oklch(0.696 0.17 162.48);              /* emerald-500 */
    --radius: 0.625rem;
    --sidebar: oklch(0.97 0.001 106.424);
    --sidebar-foreground: oklch(0.216 0.006 56.043);
    --sidebar-primary: oklch(0.508 0.118 165.612);
    --sidebar-primary-foreground: oklch(0.979 0.021 166.113);
    --sidebar-accent: oklch(0.923 0.003 48.717);
    --sidebar-accent-foreground: oklch(0.216 0.006 56.043);
    --sidebar-border: oklch(0.923 0.003 48.717);
    --sidebar-ring: oklch(0.696 0.17 162.48);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    @apply font-sans antialiased;
  }
  body {
    @apply bg-background text-foreground;
  }
}

@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

