      <span className={cn("absolute top-1.5 left-0 size-2 rounded-full", tone)} aria-hidden />
      <div className="flex items-baseline justify-between gap-2">
        <h4 className="text-xs font-medium">{title}</h4>
        <span className="text-[0.688rem] text-muted-foreground">{label}</span>
      </div>
      {children && <div className="mt-1 space-y-0.5 text-xs text-pretty text-muted-foreground">{children}</div>}
    </li>
  )
}

function DataFlowTab({ turn, historyMessages }: { turn: ChatTurn; historyMessages: number }) {
  const { retrieval, embedding, generation, review } = turn.inspector
  const preflightStopped = !retrieval.ran && Boolean(turn.reason)
  const park = parkName(turn.selected_park)
  return (
    <div className="space-y-5">
      <ol>
        <Step state="done" title="Browser → local server (127.0.0.1)">
          Question, selected park ({park}) and {historyMessages} prior message(s) from this tab's memory.
        </Step>
        <Step state={preflightStopped ? "stopped" : "done"} title="Local preflight checks">
          {preflightStopped ? `Stopped locally: ${turn.reason?.code}. Nothing left this computer.` : "Selected-park, live-information and private-record checks passed locally."}
        </Step>
        <Step state={embedding.status === "not_requested" ? "skipped" : "done"} title="Query embedding">
          {embedding.status === "cache_hit" && <p>Vector already in the local cache; no Azure call for embedding.</p>}
          {embedding.status === "sent_to_azure" && <p>Retrieval query sent to the one Azure endpoint ({embedding.deployment}).</p>}
          {embedding.status !== "not_requested" && <p className="tabular-nums">Elapsed {formatMs(embedding.elapsed_ms)}</p>}
        </Step>
        <Step state={retrieval.ran ? "done" : "skipped"} title="Local search: SQLite + NumPy cosine + BM25 + fusion">
          {retrieval.ran && (
            <p className="tabular-nums">
              {formatCount(retrieval.candidate_count)} candidates from {formatCount(retrieval.eligible_count)} saved {park} passages ·{" "}
              {formatMs(retrieval.timings_ms.retrieval_ms)}
            </p>
          )}
        </Step>
        <Step state={retrieval.ran && retrieval.rerank_enabled ? "done" : "skipped"} title="Local reranking (cross-encoder on this machine)">
          {retrieval.ran && retrieval.rerank_enabled && <p className="tabular-nums">{formatMs(retrieval.timings_ms.rerank_ms)}</p>}
        </Step>
        <Step state={generation.ran ? "done" : "skipped"} title="Answer drafting (Luna on the same Azure resource)">
          {generation.ran && (
            <>
              <p>Sent: question, {retrieval.context_count} selected snippet(s) and bounded prior conversation.</p>
              <p>Returned model: {generation.returned_model ?? NOT_CAPTURED}</p>
              <p className="tabular-nums">
                Tokens {formatCount(generation.input_tokens)} in / {formatCount(generation.output_tokens)} out · {formatMs(generation.elapsed_ms)} · est.{" "}
                {formatUsd(generation.cost_estimate_usd)}
              </p>
            </>
          )}
        </Step>
        <Step
          state={review.status === "not_run" ? "skipped" : review.status === "error" ? "failed" : "done"}
          title="Claim source review (Luna, cited sources only)"
        >
          {review.status !== "not_run" && (
            <>
              <p>
                {review.status === "passed" && "All drafted claims passed source review."}
                {review.status === "partially_withheld" && `${review.withheld_claims} unsupported claim(s) withheld.`}
                {review.status === "all_withheld" && "Every drafted claim was withheld."}
                {review.status === "error" && `Review did not complete validly (${review.validation_reason ?? review.error_message ?? "error"}). Nothing was delivered.`}
              </p>
              <p>Returned model: {review.model ?? NOT_CAPTURED}</p>
              <p className="tabular-nums">
                Tokens {formatCount(review.input_tokens)} in / {formatCount(review.output_tokens)} out · {formatMs(review.elapsed_ms)} · est.{" "}
                {formatUsd(review.cost_estimate_usd)}
              </p>
            </>
          )}
        </Step>
        <Step state={turn.inspector.guard_errors.length ? "failed" : retrieval.ran ? "done" : "skipped"} title="Deterministic citation, number and quotation guards">
          {turn.inspector.guard_errors.length > 0 && <p>Failed: {turn.inspector.guard_errors.join(", ")}</p>}
        </Step>
        <Step state="done" title="Local server → browser">
          {turn.status === "answer"
            ? `Reviewed answer with ${turn.claims.length} claim(s) and ${turn.sources.length} saved source page(s).`
            : `${turn.status === "refusal" ? "Refusal" : "Clarification"} without source cards (${turn.reason?.code ?? "no reason recorded"}).`}
        </Step>
      </ol>
      <Section title="Totals">
        <dl>
          <Row label="Measured in browser" value={formatMs(turn.timing.request_ms)} hint="Server-side request time" />
          <Row label="Shared pipeline time" value={formatMs(turn.timing.pipeline_ms)} />
          <Row label="Estimated model cost (this turn)" value={formatUsd(turn.inspector.total_cost_estimate_usd)} />
        </dl>
        <p className="text-xs text-pretty text-muted-foreground">
          Cost estimates use published prices and provider-reported tokens; they are not billing statements. “Not captured” means no value was recorded, which is
          different from zero.
        </p>
      </Section>
    </div>
  )
}

export function Inspector({ turn, historyMessages }: { turn: ChatTurn | null; historyMessages: number }) {
  if (!turn) {
