import { captureAge } from "@/lib/format"
import { useChat } from "@/lib/use-chat"
import { cn } from "@/lib/utils"

type View = "chat" | "corpus"
type PendingAction = { kind: "park"; park: ParkCode | null } | { kind: "new" }

const DESKTOP = "(min-width: 1280px)"

function useMediaQuery(query: string) {
  return useSyncExternalStore(
    (notify) => {
      const list = window.matchMedia(query)
      list.addEventListener("change", notify)
      return () => list.removeEventListener("change", notify)
    },
    () => window.matchMedia(query).matches,
  )
}

function Sidebar({
  park,
  view,
  meta,
  hasConversation,
  onPark,
  onNew,
  onView,
  onAbout,
}: {
  park: ParkCode | null
  view: View
  meta: Meta | null
  hasConversation: boolean
  onPark: (park: ParkCode | null) => void
  onNew: () => void
  onView: (view: View) => void
  onAbout: () => void
}) {
  const stats = meta?.parks.find((item) => item.code === park)
  return (
    <div className="flex h-full flex-col gap-6 p-4">
      <div className="flex items-center gap-2.5">
        <span className="flex size-8 items-center justify-center rounded-lg bg-primary text-primary-foreground">
          <TreesIcon className="size-4" aria-hidden />
        </span>
        <div>
          <p className="text-sm font-semibold">ParkGuide</p>
          <p className="text-xs text-muted-foreground">Saved official NPS sources</p>
        </div>
      </div>

      <div className="space-y-2">
        <label htmlFor="park-select" className="text-xs font-medium text-muted-foreground">
