              <SelectValue placeholder="Choose a park" />
            </SelectTrigger>
            <SelectContent>
              {PARKS.map((option) => (
                <SelectItem key={option.code} value={option.code}>
                  {option.name} National Park
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
