export default function App() {
  const [park, setPark] = useState<ParkCode | null>(null)
  const [view, setView] = useState<View>("chat")
  const [meta, setMeta] = useState<Meta | null>(null)
  const [metaError, setMetaError] = useState<string | null>(null)
  const [inspectorOpen, setInspectorOpen] = useState(false)
  const [inspectorTurnId, setInspectorTurnId] = useState<string | null>(null)
  const [evidence, setEvidence] = useState<{ turnId: string; number: number } | null>(null)
  const [menuOpen, setMenuOpen] = useState(false)
  const [aboutOpen, setAboutOpen] = useState(false)
  const [confirm, setConfirm] = useState<PendingAction | null>(null)
  const desktop = useMediaQuery(DESKTOP)
  const chat = useChat(park)

  useEffect(() => {
    getMeta()
      .then(setMeta)
      .catch((error) => setMetaError(error instanceof ApiError ? error.message : "Could not load corpus metadata."))
  }, [])

  const doneTurns = useMemo(() => chat.turns.flatMap((turn) => (turn.phase === "done" ? [turn] : [])), [chat.turns])
  const inspected = doneTurns.find((turn) => turn.id === inspectorTurnId) ?? doneTurns.at(-1) ?? null
  const historyMessages = inspected ? Math.min(MAX_HISTORY_MESSAGES, 2 * doneTurns.indexOf(inspected)) : 0
  const evidenceTurn = doneTurns.find((turn) => turn.id === evidence?.turnId) ?? null

  const clearConversation = useCallback(() => {
    chat.reset()
    setInspectorTurnId(null)
    setInspectorOpen(false)
    setEvidence(null)
  }, [chat])

  const apply = useCallback(
    (action: PendingAction) => {
      clearConversation()
      if (action.kind === "park") setPark(action.park)
      setMenuOpen(false)
    },
    [clearConversation],
  )

  const request = (action: PendingAction) => {
    if (action.kind === "park" && action.park === park) return
    if (chat.turns.length > 0) setConfirm(action)
    else apply(action)
  }

  const chatReady = meta?.chat.ready ?? false
  const sidebar = (
    <Sidebar
      park={park}
      view={view}
      meta={meta}
      hasConversation={chat.turns.length > 0}
