      <Sheet open={menuOpen} onOpenChange={setMenuOpen}>
        <SheetContent side="left" className="w-72 bg-sidebar p-0">
          <SheetHeader className="sr-only">
            <SheetTitle>Menu</SheetTitle>
            <SheetDescription>Park selection and navigation</SheetDescription>
          </SheetHeader>
          {sidebar}
        </SheetContent>
      </Sheet>

      <Sheet open={view === "chat" && !desktop && inspectorOpen} onOpenChange={setInspectorOpen}>
        <SheetContent side="right" className="w-full gap-0 p-0 sm:max-w-lg">
          <SheetHeader className="border-b pr-12">
            <SheetTitle>Inspector</SheetTitle>
            <SheetDescription>Evidence, retrieval and data flow for one turn.</SheetDescription>
          </SheetHeader>
          <div className="min-h-0 flex-1">{inspector}</div>
        </SheetContent>
      </Sheet>

      <EvidenceDialog
        response={evidenceTurn?.response ?? null}
        sourceNumber={evidence?.number ?? null}
        onOpenChange={(open) => !open && setEvidence(null)}
      />
      <HowItWorks open={aboutOpen} onOpenChange={setAboutOpen} meta={meta} />

      <AlertDialog open={Boolean(confirm)} onOpenChange={(open) => !open && setConfirm(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              {confirm?.kind === "new" ? "Start a new conversation?" : confirm?.kind === "park" && confirm.park ? `Switch to ${parkName(confirm.park)}?` : "Clear the selected park?"}
            </AlertDialogTitle>
            <AlertDialogDescription>
              This clears the current conversation and its evidence from this tab. It cannot be undone. A reply still in progress on the server will be ignored.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => {
                if (confirm) apply(confirm)
                setConfirm(null)
              }}
            >
              {confirm?.kind === "new" ? "Start new" : "Clear conversation"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </TooltipProvider>
